-- Private uploaded files. Storage keys are generated by the application, never derived from user input.
create table media_assets (
    id               uuid         primary key,
    storage_key      varchar(200) not null unique,
    filename         varchar(255) not null,
    content_type     varchar(100) not null,
    size_bytes       bigint       check (size_bytes >= 0),
    sha256           varchar(64),
    -- AssetPurpose code: 0 VIDEO, 1 DOCUMENT, 2 BRANDING_IMAGE.
    purpose          smallint     not null check (purpose between 0 and 2),
    -- AssetStatus code: 0 UPLOADING, 1 VALIDATING, 2 AVAILABLE, 3 REJECTED.
    status           smallint     not null check (status between 0 and 3),
    rejection_reason varchar(500),
    duration_seconds integer      check (duration_seconds >= 0),
    uploaded_by      uuid         not null references users (id),
    created_at       timestamptz  not null,
    updated_at       timestamptz  not null
);

create index media_assets_status_idx on media_assets (status, updated_at);
create index media_assets_uploader_idx on media_assets (uploaded_by, status);

alter table workspace add column logo_asset_id uuid references media_assets (id);

-- A course has exactly one immutable author. Content lives in editions (course_versions): one mutable DRAFT,
-- numbered immutable PUBLISHED editions. Catalog metadata is read from the latest published edition.
create table courses (
    id          uuid         primary key,
    author_id   uuid         not null references users (id),
    title       varchar(200) not null,
    -- CourseStatus code: 0 ACTIVE, 1 ARCHIVED.
    status      smallint     not null check (status between 0 and 1),
    created_at  timestamptz  not null,
    updated_at  timestamptz  not null,
    archived_at timestamptz,
    version     bigint       not null default 0
);

create index courses_author_idx on courses (author_id, updated_at desc, id);

create table course_versions (
    id                  uuid         primary key,
    course_id           uuid         not null references courses (id),
    edition             integer      check (edition > 0),
    -- EditionStatus code: 0 DRAFT, 1 PUBLISHED.
    status              smallint     not null check (status between 0 and 1),
    title               varchar(200) not null,
    description         text         not null default '',
    based_on_version_id uuid         references course_versions (id),
    created_at          timestamptz  not null,
    updated_at          timestamptz  not null,
    published_at        timestamptz,
    version             bigint       not null default 0,
    unique (course_id, edition),
    unique (course_id, id),
    check ((status = 0 and edition is null and published_at is null)
        or (status = 1 and edition is not null and published_at is not null))
);

create unique index course_versions_draft_idx on course_versions (course_id) where status = 0;
create index course_versions_catalog_idx on course_versions (course_id, edition desc) where status = 1;

create table sections (
    id                uuid         primary key,
    course_version_id uuid         not null references course_versions (id),
    title             varchar(200) not null,
    position          integer      not null check (position >= 0),
    unique (course_version_id, position),
    unique (course_version_id, id)
);

create table lessons (
    id                uuid         primary key,
    course_version_id uuid         not null references course_versions (id),
    section_id        uuid         not null,
    title             varchar(200) not null,
    position          integer      not null check (position >= 0),
    body_html         text         not null default '',
    video_asset_id    uuid         references media_assets (id),
    -- VideoProvider code: 0 YOUTUBE, 1 VIMEO.
    video_provider    smallint     check (video_provider between 0 and 1),
    video_ref         varchar(64),
    required          boolean      not null default true,
    foreign key (course_version_id, section_id) references sections (course_version_id, id),
    unique (section_id, position),
    unique (course_version_id, id),
    check ((video_provider is null) = (video_ref is null)),
    check (video_asset_id is null or video_provider is null)
);

create index lessons_video_asset_idx on lessons (video_asset_id);

create table lesson_resources (
    lesson_id uuid    not null references lessons (id),
    asset_id  uuid    not null references media_assets (id),
    position  integer not null check (position >= 0),
    primary key (lesson_id, position)
);

create index lesson_resources_asset_idx on lesson_resources (asset_id);
